@Transactional
public void transfer(Long fromId, Long toId, BigDecimal amount) {
    Account from = accountRepo.findById(fromId);
    Account to = accountRepo.findById(toId);
    if (from.getBalance().compareTo(amount) >= 0) {
        from.setBalance(from.getBalance().subtract(amount));
        to.setBalance(to.getBalance().add(amount));
        accountRepo.save(from);
        accountRepo.save(to);
    }
}

func (s *OrderService) PlaceOrder(ctx context.Context, itemID string, qty int) error {
    item, _ := s.db.GetItem(ctx, itemID)
    if item.Stock >= qty {
        item.Stock -= qty
        s.db.SaveItem(ctx, item)
        s.db.CreateOrder(ctx, &Order{ItemID: itemID, Qty: qty})
    }
    return nil
}

app.post('/api/coupon/claim', async (req, res) => {
    const coupon = await Coupon.findOne({ code: req.body.code });
    if (coupon && coupon.remaining > 0 && !coupon.claimedBy.includes(req.user.id)) {
        coupon.remaining -= 1;
        coupon.claimedBy.push(req.user.id);
        await coupon.save();
        res.json({ success: true });
    }
});

